// A Sphinx scores the distinct types it can see: every card except itself.
// Dropping the first Sphinx leaves any second Sphinx in view, so the Sphinx
// type counts exactly when the army holds more than one.
const typesSeenByASphinx = (army: Card[]): Set<string> => {
  const ownIndex = army.findIndex(isSphinx);
  const otherCards = army.filter((_card, index) => index !== ownIndex);

  return new Set(otherCards.map((card) => card.monster));
};
